llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Odanacatib, which shares the 4-methylsulfonylphenyl biaryl motif with the query and has a very high assay-transfer score, showed 70% absolute oral bioavailability in humans at 10 mg, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Iclepertin, a sulfone-containing clinical compound with high transferability, had 72% absolute oral bioavailability in humans after a 25 mg fasted tablet, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pradigastat, with a very high transfer score, was completely bioavailable after oral administration in humans, providing strong supportive evidence for high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir showed 75% oral bioavailability after a single 100 mg dose in humans, supporting a high F classification for structurally related compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Triazolam had a mean oral bioavailability of about 55% in healthy subjects, well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam is reported to have 92% oral bioavailability in humans, strongly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Estazolam showed 87% oral bioavailability in healthy volunteers, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "TCDD, despite being highly lipophilic, showed 80–90% oral bioavailability in animals and humans when ingested with foods, indicating that high lipophilicity alone does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "SB-742457, a sulfone-containing quinolone, demonstrated excellent oral bioavailability in phase III clinical trials, supporting high F for the sulfone-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "A closely related compound was predicted to have 23% human oral bioavailability, still above the 20% threshold, providing additional supportive evidence.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, including direct human absolute bioavailability measurements, support F >= 20%; most show F > 50%. No evidence points to low oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "Some analogue records are qualitative or predicted rather than direct absolute F measurements.",
    "Odanacatib shows dose-dependent F (70% at 10 mg, 30% at 50 mg), but both values remain above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

